var rgb2 = {
  name: "rgb",
  min: [0, 0, 0],
  max: [255, 255, 255],
  channel: ["red", "green", "blue"],
  alias: ["RGB"]
};
var rgb_default2 = rgb2;

// node_modules/color-space/hsl.js
rgb_default2.hsl = function(rgb3) {
  var r = rgb3[0] / 255, g = rgb3[1] / 255, b = rgb3[2] / 255, min3 = Math.min(r, g, b), max3 = Math.max(r, g, b), delta = max3 - min3, h, s, l;
  if (max3 === min3) {
    h = 0;
  } else if (r === max3) {
    h = (g - b) / delta;
  } else if (g === max3) {
    h = 2 + (b - r) / delta;
  } else if (b === max3) {
    h = 4 + (r - g) / delta;
  }
  h = Math.min(h * 60, 360);
  if (h < 0) {
    h += 360;
  }
  l = (min3 + max3) / 2;
  if (max3 === min3) {
    s = 0;
  } else if (l <= 0.5) {
    s = delta / (max3 + min3);
  } else {
    s = delta / (2 - max3 - min3);
  }
  return [h, s * 100, l * 100];
};

